// Postgres database adapter for 9Router.
//
// Mirroring src/lib/db/adapters/postgresMemoryAdapter.js, postgresSchema.js,
// and memoryEngine.js:
//   - Schema isolation: nr_<sha256(dataDir)[..16]> schema isolation per instance
//   - Identifiers quoting: camelCase preserved via double-quoting ("providerConnections")
//   - Type mapping: REAL -> DOUBLE PRECISION (preserving 8-byte float precision),
//     AUTOINCREMENT -> BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY
//   - Full table DDL & index DDL generation
//   - Additive table migrations
//   - Connection configuration & URL parameter injection (options=-c search_path=...)
//   - Fast memory tiering & write-behind synchronization queue
//   - SQLite to Postgres query translation

use std::collections::{HashMap, HashSet};
use std::sync::{Arc, Mutex, RwLock};
use std::time::{Duration, Instant};

use ring::digest::{digest, SHA256};
use serde::{Deserialize, Serialize};
use serde_json::Value;

/// Schema version matching schema.js
pub const SCHEMA_VERSION: u32 = 4;

/// Tables that flush immediately to Postgres on write rather than waiting in the write-behind queue.
/// Any loss of credentials, keys, or core routing configuration is a security/availability incident.
pub const CRITICAL_TABLES: &[&str] = &[
    "settings",
    "apiKeys",
    "providerConnections",
    "providerNodes",
    "proxyPools",
    "combos",
    "_meta",
    "kv",
];

/// Tables loaded on first touch rather than at boot.
pub const LAZY_TABLES: &[&str] = &[
    "kv",
    "providerConnections",
    "usageHistory",
    "requestDetails",
];

/// Tables whose integer key the database generates when one is not supplied.
pub const IDENTITY_TABLES: &[&str] = &["usageHistory"];

/// Maximum queue size before forcing an immediate write-behind flush.
pub const MAX_QUEUE_BEFORE_FLUSH: usize = 200;

/// Default write-behind queue flush interval in milliseconds.
pub const DEFAULT_FLUSH_INTERVAL_MS: u64 = 250;

