/// Get table definition by name.
pub fn get_table_def(name: &str) -> Option<&'static TableDef> {
    ALL_TABLE_DEFS.iter().find(|t| t.name == name)
}

// ============================================================================
// Schema Name Generation & Identifier Quoting
// ============================================================================

/// Deterministic, valid schema name for a DATA_DIR, or None when unset or whitespace.
/// Uses SHA256 truncated to 16 hex characters prefixed with "nr_".
pub fn data_dir_schema(data_dir: Option<&str>) -> Option<String> {
    let dir = data_dir?.trim();
    if dir.is_empty() {
        return None;
    }
    let digest = digest(&SHA256, dir.as_bytes());
    let hex: String = digest.as_ref().iter().map(|b| format!("{:02x}", b)).collect();
    Some(format!("nr_{}", &hex[..16]))
}

/// Quote an identifier for Postgres to prevent folding camelCase identifiers to lowercase.
pub fn pg_ident(name: &str) -> String {
    format!("\"{}\"", name.replace('"', "\"\""))
}

/// SQLite type text -> Postgres type text.
/// REAL -> DOUBLE PRECISION (SQLite REAL is 8-byte, Postgres REAL is 4-byte; prevents rounding financial fields)
/// INTEGER PRIMARY KEY AUTOINCREMENT -> BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY
pub fn pg_column_type(sqlite_type: &str) -> String {
    let trimmed = sqlite_type.trim();
    if trimmed.eq_ignore_ascii_case("INTEGER PRIMARY KEY AUTOINCREMENT") {
        "BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY".to_string()
    } else if trimmed.to_ascii_uppercase().starts_with("REAL") {
        "DOUBLE PRECISION".to_string()
    } else {
        trimmed.to_string()
    }
}

// ============================================================================
// Table & Index DDL Generation
// ============================================================================

/// Build CREATE TABLE IF NOT EXISTS statement for a table in Postgres.
pub fn build_create_table_sql_postgres(def: &TableDef) -> String {
    let is_identity = IDENTITY_TABLES.contains(&def.name);
    let mut columns = Vec::new();

    for (col_name, col_type) in def.columns {
        if is_identity && col_type.to_ascii_uppercase().ends_with("AUTOINCREMENT") {
            // Identity column already carries PRIMARY KEY
            columns.push(format!("{} {}", pg_ident(col_name), pg_column_type(col_type)));
            continue;
        }
        columns.push(format!("{} {}", pg_ident(col_name), pg_column_type(col_type)));
    }

    if let Some(pk) = def.primary_key {
        columns.push(pk.to_string());
    }

    format!(
        "CREATE TABLE IF NOT EXISTS {} ({})",
        pg_ident(def.name),
        columns.join(", ")
    )
}

/// Helper: split index column list safely respecting nested parentheses.
fn split_index_columns(input: &str) -> Vec<String> {
    let mut out = Vec::new();
    let mut depth = 0;
    let mut current = String::new();

    for ch in input.chars() {
        if ch == '(' {
            depth += 1;
        } else if ch == ')' {
            depth -= 1;
        } else if ch == ',' && depth == 0 {
            if !current.trim().is_empty() {
                out.push(current.trim().to_string());
            }
            current.clear();
            continue;
        }
        current.push(ch);
    }
    if !current.trim().is_empty() {
        out.push(current.trim().to_string());
    }
    out
}

/// Index DDL with the table and every column quoted, preserving ASC/DESC modifiers.
/// Converts "ON providerConnections(provider, isActive)" to "ON \"providerConnections\" (\"provider\", \"isActive\")".
pub fn build_create_index_sql_postgres(statement: &str) -> String {
    let on_pos = match statement.to_ascii_uppercase().find(" ON ") {
        Some(pos) => pos + 4,
        None => return statement.to_string(),
    };

    let prefix = &statement[..on_pos];
    let remainder = &statement[on_pos..];

    let paren_open = match remainder.find('(') {
        Some(pos) => pos,
        None => return statement.to_string(),
    };
    let paren_close = match remainder.rfind(')') {
        Some(pos) => pos,
        None => return statement.to_string(),
    };

    let table_name = remainder[..paren_open].trim();
    let columns_part = &remainder[paren_open + 1..paren_close];

    let parts = split_index_columns(columns_part);
    let mut quoted_cols = Vec::new();

    for part in parts {
        let trimmed = part.trim();
        let tokens: Vec<&str> = trimmed.split_whitespace().collect();
        if tokens.is_empty() {
            continue;
        }
        if tokens.len() == 1 {
            quoted_cols.push(pg_ident(tokens[0]));
        } else if tokens.len() == 2 && (tokens[1].eq_ignore_ascii_case("ASC") || tokens[1].eq_ignore_ascii_case("DESC")) {
            quoted_cols.push(format!("{} {}", pg_ident(tokens[0]), tokens[1].to_ascii_uppercase()));
        } else {
            quoted_cols.push(trimmed.to_string());
        }
    }

    format!(
        "{}{} ({})",
        prefix,
        pg_ident(table_name),
        quoted_cols.join(", ")
    )
}

/// Every statement needed to bring an empty Postgres up to the current schema.
pub fn build_postgres_schema_statements() -> Vec<String> {
    let mut statements = Vec::new();
    for def in ALL_TABLE_DEFS {
        statements.push(build_create_table_sql_postgres(def));
        for index in def.indexes {
            statements.push(build_create_index_sql_postgres(index));
        }
    }
    statements
}

/// Additive migration statements to bring older database schemas up to date idempotently.
pub fn build_migration_statements() -> Vec<String> {
    vec![
        r#"ALTER TABLE "combos" ADD COLUMN IF NOT EXISTS "strategy" TEXT DEFAULT 'fallback'"#.to_string(),
        r#"ALTER TABLE "combos" ADD COLUMN IF NOT EXISTS "matchRules" TEXT DEFAULT '[]'"#.to_string(),
        r#"ALTER TABLE "combos" ADD COLUMN IF NOT EXISTS "customPrompt" TEXT DEFAULT ''"#.to_string(),
        r#"ALTER TABLE "usageHistory" ADD COLUMN IF NOT EXISTS "cachedTokens" INTEGER DEFAULT 0"#.to_string(),
        r#"ALTER TABLE "apiKeys" ADD COLUMN IF NOT EXISTS "budgetUsd" DOUBLE PRECISION"#.to_string(),
        r#"ALTER TABLE "apiKeys" ADD COLUMN IF NOT EXISTS "budgetResetHours" DOUBLE PRECISION"#.to_string(),
        r#"ALTER TABLE "apiKeys" ADD COLUMN IF NOT EXISTS "budgetWindowStartedAt" TEXT"#.to_string(),
        r#"ALTER TABLE "apiKeys" ADD COLUMN IF NOT EXISTS "billingMode" TEXT DEFAULT 'credits'"#.to_string(),
        r#"ALTER TABLE "apiKeys" ADD COLUMN IF NOT EXISTS "byokProvider" TEXT"#.to_string(),
        r#"ALTER TABLE "apiKeys" ADD COLUMN IF NOT EXISTS "regenerateVersion" INTEGER DEFAULT 0"#.to_string(),
        r#"ALTER TABLE "apiKeys" ADD COLUMN IF NOT EXISTS "metadata" TEXT DEFAULT '{}'"#.to_string(),
        r#"ALTER TABLE "apiKeys" ADD COLUMN IF NOT EXISTS "updatedAt" TEXT"#.to_string(),
    ]
}

/// Full bootstrap statements including optional schema creation and search_path setup.
pub fn build_bootstrap_schema_sql(schema: Option<&str>) -> Vec<String> {
    let mut statements = Vec::new();
    if let Some(s) = schema.filter(|s| !s.trim().is_empty()) {
        statements.push(format!("CREATE SCHEMA IF NOT EXISTS {}", pg_ident(s)));
        statements.push(format!("SET search_path TO {}", pg_ident(s)));
    }
    statements.extend(build_postgres_schema_statements());
    statements.extend(build_migration_statements());
    statements
}

// ============================================================================
// Data Mapping & Primary Key Resolution
// ============================================================================

/// Returns the primary key columns for a table.
pub fn conflict_columns(table: &str) -> Vec<String> {
    if let Some(def) = get_table_def(table) {
        if let Some(pk) = def.primary_key {
            if let Some(start) = pk.find('(') {
                if let Some(end) = pk.rfind(')') {
                    let cols = &pk[start + 1..end];
                    return cols.split(',').map(|c| c.trim().to_string()).filter(|c| !c.is_empty()).collect();
                }
            }
        }
        if let Some((first_col, _)) = def.columns.first() {
            return vec![first_col.to_string()];
        }
    }
    vec!["id".to_string()]
}

/// Primary key string identifier for a row (for write-behind deduplication).
pub fn primary_key_for_row(table: &str, row: &HashMap<String, Value>) -> String {
    let keys = conflict_columns(table);
    if keys.is_empty() {
        return row.get("id").map(|v| v.to_string()).unwrap_or_else(|| "default".to_string());
    }
    keys.iter()
        .map(|k| {
            let val_str = match row.get(k) {
                Some(Value::String(s)) => s.clone(),
                Some(Value::Number(n)) => n.to_string(),
                Some(Value::Bool(b)) => b.to_string(),
                Some(Value::Null) | None => String::new(),
                Some(other) => other.to_string(),
            };
            format!("{}:{}", k, val_str)
        })
        .collect::<Vec<_>>()
        .join("|")
}

/// Build an upsert statement for Postgres (INSERT ... ON CONFLICT (...) DO UPDATE ...).
pub fn build_upsert_sql(table: &str, columns: &[&str]) -> String {
    if columns.is_empty() {
        return String::new();
    }
    let placeholders: Vec<String> = (1..=columns.len()).map(|i| format!("${}", i)).collect();
    let quoted_cols: Vec<String> = columns.iter().map(|c| pg_ident(c)).collect();

    let conflict_cols = conflict_columns(table);
    let conflict_quoted: Vec<String> = conflict_cols.iter().map(|c| pg_ident(c)).collect();

    let updates: Vec<String> = columns
        .iter()
        .filter(|c| !conflict_cols.contains(&c.to_string()))
        .map(|c| format!("{} = EXCLUDED.{}", pg_ident(c), pg_ident(c)))
        .collect();

    let target = format!("ON CONFLICT ({})", conflict_quoted.join(", "));
    let verb = if updates.is_empty() {
        format!("{} DO NOTHING", target)
    } else {
        format!("{} DO UPDATE SET {}", target, updates.join(", "))
    };

    format!(
        "INSERT INTO {} ({}) VALUES ({}) {}",
        pg_ident(table),
        quoted_cols.join(", "),
        placeholders.join(", "),
        verb
    )
}

/// Build a DELETE statement for Postgres using conflict columns.
pub fn build_delete_sql(table: &str) -> String {
    let conflict_cols = conflict_columns(table);
    let where_clause = conflict_cols
        .iter()
        .enumerate()
        .map(|(i, c)| format!("{} = ${}", pg_ident(c), i + 1))
        .collect::<Vec<_>>()
        .join(" AND ");

    format!("DELETE FROM {} WHERE {}", pg_ident(table), where_clause)
}

/// Build a SELECT statement for Postgres.
pub fn build_select_sql(table: &str, columns: &[&str]) -> String {
    let cols = if columns.is_empty() {
        "*".to_string()
    } else {
        columns.iter().map(|c| pg_ident(c)).collect::<Vec<_>>().join(", ")
    };
    format!("SELECT {} FROM {}", cols, pg_ident(table))
}

/// Build a SELECT by primary key statement for Postgres.
pub fn build_select_by_pk_sql(table: &str, columns: &[&str]) -> String {
    let conflict_cols = conflict_columns(table);
    let where_clause = conflict_cols
        .iter()
        .enumerate()
        .map(|(i, c)| format!("{} = ${}", pg_ident(c), i + 1))
        .collect::<Vec<_>>()
        .join(" AND ");

    let select_part = build_select_sql(table, columns);
    format!("{} WHERE {}", select_part, where_clause)
}

// ============================================================================
// Connection Management & Configuration
// ============================================================================

/// Connection configuration for Postgres.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct PgConfig {
    pub connection_string: String,
    pub effective_connection_string: String,
    pub schema: Option<String>,
    pub max_connections: u32,
    pub idle_timeout: Duration,
    pub connection_timeout: Duration,
    pub force_ssl: bool,
    pub data_dir: Option<String>,
}

impl PgConfig {
    /// Detects configuration from environment variables (DATABASE_URL / POSTGRES_URL).
    pub fn from_env() -> Option<Self> {
        let conn_str = std::env::var("DATABASE_URL")
            .or_else(|_| std::env::var("POSTGRES_URL"))
            .ok()?;
        let data_dir = std::env::var("DATA_DIR").ok();
        Some(Self::init(conn_str, data_dir))
    }

    /// Detects configuration with an explicit data_dir override.
    pub fn from_env_with_data_dir(data_dir: Option<&str>) -> Option<Self> {
        let conn_str = std::env::var("DATABASE_URL")
            .or_else(|_| std::env::var("POSTGRES_URL"))
            .ok()?;
        Some(Self::init(conn_str, data_dir.map(|s| s.to_string())))
    }

    /// Construct a new PgConfig with optional overrides.
    pub fn new(
        connection_string: &str,
        data_dir: Option<&str>,
        force_ssl: bool,
        max_pool: Option<u32>,
    ) -> Result<Self, String> {
        let conn_str = connection_string.trim();
        if conn_str.is_empty() {
            return Err("Postgres connection string cannot be empty".to_string());
        }

        let schema = data_dir_schema(data_dir);
        let effective_connection_string = Self::compute_effective_connection_string(conn_str, schema.as_deref());

        let max_connections = max_pool.unwrap_or_else(|| {
            std::env::var("DB_POOL_MAX")
                .ok()
                .and_then(|v| v.parse::<u32>().ok())
                .unwrap_or(5)
        });

        Ok(Self {
            connection_string: conn_str.to_string(),
            effective_connection_string,
            schema,
            max_connections,
            idle_timeout: Duration::from_millis(30_000),
            connection_timeout: Duration::from_millis(10_000),
            force_ssl,
            data_dir: data_dir.map(|s| s.to_string()),
        })
    }

    fn init(conn_str: String, data_dir: Option<String>) -> Self {
        let force_ssl = std::env::var("DB_SSL").map(|v| v == "true").unwrap_or(false);
        let max_connections = std::env::var("DB_POOL_MAX")
            .ok()
            .and_then(|v| v.parse::<u32>().ok())
            .unwrap_or(5);
        let schema = data_dir_schema(data_dir.as_deref());
        let effective_connection_string = Self::compute_effective_connection_string(&conn_str, schema.as_deref());

        Self {
            connection_string: conn_str,
            effective_connection_string,
            schema,
            max_connections,
            idle_timeout: Duration::from_millis(30_000),
            connection_timeout: Duration::from_millis(10_000),
            force_ssl,
            data_dir,
        }
    }

    /// Compute effective connection string with options=-c search_path=<schema> pinned.
    pub fn compute_effective_connection_string(conn_str: &str, schema: Option<&str>) -> String {
        let schema = match schema {
            Some(s) if !s.trim().is_empty() => s.trim(),
            _ => return conn_str.to_string(),
        };

        if let Ok(mut parsed_url) = url::Url::parse(conn_str) {
            let options_val = format!("-c search_path={}", schema);
            let mut query_pairs: Vec<(String, String)> = parsed_url
                .query_pairs()
                .filter(|(k, _)| k != "options")
                .map(|(k, v)| (k.to_string(), v.to_string()))
                .collect();
            query_pairs.push(("options".to_string(), options_val));
            parsed_url.query_pairs_mut().clear().extend_pairs(query_pairs);
            parsed_url.to_string()
        } else {
            // Not a URL (e.g. key-value string or unix socket DSN). Leave as is.
            conn_str.to_string()
        }
    }

    /// Checks if Postgres is configured in environment.
    pub fn is_configured() -> bool {
        std::env::var("DATABASE_URL").is_ok() || std::env::var("POSTGRES_URL").is_ok()
    }
}

/// Postgres connection manager and pool state tracker.
pub struct PgConnectionManager {
    config: PgConfig,
    active_connections: Arc<Mutex<u32>>,
    total_queries: Arc<Mutex<u64>>,
    failed_queries: Arc<Mutex<u64>>,
}

impl PgConnectionManager {
    pub fn new(config: PgConfig) -> Self {
        Self {
            config,
            active_connections: Arc::new(Mutex::new(0)),
            total_queries: Arc::new(Mutex::new(0)),
            failed_queries: Arc::new(Mutex::new(0)),
        }
    }

    pub fn config(&self) -> &PgConfig {
        &self.config
    }

    pub fn effective_url(&self) -> &str {
        &self.config.effective_connection_string
    }

    pub fn schema(&self) -> Option<&str> {
        self.config.schema.as_deref()
    }

    pub fn active_connections(&self) -> u32 {
        self.active_connections.lock().map(|c| *c).unwrap_or(0)
    }

    pub fn acquire_connection(&self) -> bool {
        if let Ok(mut count) = self.active_connections.lock() {
            if *count < self.config.max_connections {
                *count += 1;
                return true;
            }
        }
        false
    }

    pub fn release_connection(&self) {
        if let Ok(mut count) = self.active_connections.lock() {
            if *count > 0 {
                *count -= 1;
            }
        }
    }

    pub fn record_query_success(&self) {
        if let Ok(mut count) = self.total_queries.lock() {
            *count += 1;
        }
    }

    pub fn record_query_failure(&self) {
        if let Ok(mut total) = self.total_queries.lock() {
            *total += 1;
        }
        if let Ok(mut failed) = self.failed_queries.lock() {
            *failed += 1;
        }
    }

    pub fn stats(&self) -> (u64, u64) {
        let total = self.total_queries.lock().map(|c| *c).unwrap_or(0);
        let failed = self.failed_queries.lock().map(|c| *c).unwrap_or(0);
        (total, failed)
    }

    pub fn health_check_sql(&self) -> &'static str {
        "SELECT 1"
    }
}

// ============================================================================
// Direct SQL Query Translation (SQLite -> Postgres)
// ============================================================================

/// Translates an SQLite query to Postgres SQL:
///   1. Parameter placeholders: replaces positional ? with $1, $2, $3, ... outside of string literals
///   2. Translates INSERT OR REPLACE INTO -> INSERT INTO ... ON CONFLICT (...) DO UPDATE ...
///   3. Translates INSERT OR IGNORE INTO -> INSERT INTO ... ON CONFLICT DO NOTHING
///   4. Quotes camelCase table and column names
///   5. Translates datetime('now') -> CURRENT_TIMESTAMP
pub fn translate_sqlite_to_postgres(sql: &str) -> String {
    let mut out = String::with_capacity(sql.len() + 16);
    let mut in_single_quote = false;
    let mut in_double_quote = false;
    let mut param_index = 1usize;
    let chars: Vec<char> = sql.chars().collect();
    let mut i = 0;

    while i < chars.len() {
        let ch = chars[i];
        if ch == '\'' && !in_double_quote {
            // Check for escaped quote ''
            if in_single_quote && i + 1 < chars.len() && chars[i + 1] == '\'' {
                out.push('\'');
                out.push('\'');
                i += 2;
                continue;
            }
            in_single_quote = !in_single_quote;
            out.push(ch);
            i += 1;
            continue;
        }
        if ch == '"' && !in_single_quote {
            in_double_quote = !in_double_quote;
            out.push(ch);
            i += 1;
            continue;
        }

        if !in_single_quote && !in_double_quote && ch == '?' {
            out.push('$');
            out.push_str(&param_index.to_string());
            param_index += 1;
            i += 1;
            continue;
        }

        out.push(ch);
        i += 1;
    }

    // Handle INSERT OR REPLACE / INSERT OR IGNORE dialect differences
    let mut translated = out;
    if translated.to_ascii_uppercase().starts_with("INSERT OR REPLACE INTO ") {
        translated = translated.replacen("INSERT OR REPLACE INTO ", "INSERT INTO ", 1);
        translated = translated.replacen("insert or replace into ", "INSERT INTO ", 1);
    } else if translated.to_ascii_uppercase().starts_with("INSERT OR IGNORE INTO ") {
        translated = translated.replacen("INSERT OR IGNORE INTO ", "INSERT INTO ", 1);
        translated = translated.replacen("insert or ignore into ", "INSERT INTO ", 1);
        if !translated.to_ascii_uppercase().contains("ON CONFLICT") {
            translated.push_str(" ON CONFLICT DO NOTHING");
        }
    }

    // Replace SQLite specific functions
    translated = translated.replace("datetime('now')", "CURRENT_TIMESTAMP");
    translated = translated.replace("DATETIME('now')", "CURRENT_TIMESTAMP");

    // Quote unquoted camelCase table names
    let known_tables = [
        "providerConnections",
        "providerNodes",
        "proxyPools",
        "apiKeys",
        "usageHistory",
        "usageDaily",
        "requestDetails",
        "auditLog",
    ];
    for table in known_tables {
        let unquoted_pattern = format!(" {} ", table);
        let quoted_replacement = format!(" \"{}\" ", table);
        translated = translated.replace(&unquoted_pattern, &quoted_replacement);

        // Also check if ends with table or preceded by FROM/INTO
        if translated.ends_with(table) {
            let len = translated.len() - table.len();
            translated.truncate(len);
            translated.push_str(&format!("\"{}\"", table));
        }
    }

    translated
}

// ============================================================================
// Fast Memory Tiering & Write-Behind Synchronization
// ============================================================================

/// Write operation queued in write-behind memory tier.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub enum PgWriteOp {
    Upsert {
        table: String,
        row: HashMap<String, Value>,
    },
    Delete {
        table: String,
        keys: HashMap<String, Value>,
    },
}

impl PgWriteOp {
    pub fn table(&self) -> &str {
        match self {
            Self::Upsert { table, .. } => table,
            Self::Delete { table, .. } => table,
        }
    }
}

/// Queued item with timestamp and identity.
#[derive(Debug, Clone)]
pub struct PgWriteItem {
    pub op: PgWriteOp,
    pub queued_at: Instant,
}

/// In-memory fast tier with write-behind persistence queue to Postgres.
pub struct PgMemoryAdapter {
    config: PgConfig,
    tables: Arc<RwLock<HashMap<String, Vec<HashMap<String, Value>>>>>,
    pk_index: Arc<RwLock<HashMap<String, HashMap<String, usize>>>>,
    api_key_index: Arc<RwLock<HashMap<String, usize>>>,
    queue: Arc<Mutex<HashMap<String, PgWriteItem>>>,
    loaded_tables: Arc<RwLock<HashSet<String>>>,
    dirty_tables: Arc<RwLock<HashSet<String>>>,
}

impl PgMemoryAdapter {
    pub fn new(config: PgConfig) -> Self {
        let initial_loaded: HashSet<String> = ALL_TABLE_DEFS
            .iter()
            .map(|t| t.name.to_string())
            .filter(|name| !LAZY_TABLES.contains(&name.as_str()))
            .collect();

        Self {
            config,
            tables: Arc::new(RwLock::new(HashMap::new())),
            pk_index: Arc::new(RwLock::new(HashMap::new())),
            api_key_index: Arc::new(RwLock::new(HashMap::new())),
            queue: Arc::new(Mutex::new(HashMap::new())),
            loaded_tables: Arc::new(RwLock::new(initial_loaded)),
            dirty_tables: Arc::new(RwLock::new(HashSet::new())),
        }
    }

    pub fn config(&self) -> &PgConfig {
        &self.config
    }

    /// Check if a table is currently marked as loaded in memory.
    pub fn is_loaded(&self, table: &str) -> bool {
        self.loaded_tables
            .read()
            .map(|set| set.contains(table))
            .unwrap_or(false)
    }

    /// Mark a lazy table as loaded into memory.
    pub fn mark_loaded(&self, table: &str) {
        if let Ok(mut set) = self.loaded_tables.write() {
            set.insert(table.to_string());
        }
    }

    /// Check if a table is critical (flushes immediately).
    pub fn is_critical_table(table: &str) -> bool {
        CRITICAL_TABLES.contains(&table)
    }

    /// Check if a table is lazy loaded.
    pub fn is_lazy_table(table: &str) -> bool {
        LAZY_TABLES.contains(&table)
    }

    /// Whether an error is deterministic (constraint violation) or transient.
    pub fn is_deterministic_error(err_msg: &str) -> bool {
        let lower = err_msg.to_lowercase();
        lower.contains("violates")
            || lower.contains("not-null")
            || lower.contains("null value")
            || lower.contains("duplicate key")
            || lower.contains("invalid input")
            || lower.contains("syntax error")
    }

    /// Insert or update a row in memory and queue for write-behind persistence.
    pub fn insert_row(&self, table: &str, row: HashMap<String, Value>) -> Result<bool, String> {
        let pk_key = primary_key_for_row(table, &row);
        let queue_key = format!("{}|{}", table, pk_key);

        // Update in-memory state with O(1) PK index
        {
            let mut tables = self.tables.write().map_err(|e| e.to_string())?;
            let list = tables.entry(table.to_string()).or_default();
            let mut pk_guard = self.pk_index.write().map_err(|e| e.to_string())?;
            let table_pks = pk_guard.entry(table.to_string()).or_default();

            if let Some(&idx) = table_pks.get(&pk_key) {
                if idx < list.len() {
                    for (k, v) in &row {
                        list[idx].insert(k.clone(), v.clone());
                    }
                }
            } else {
                let idx = list.len();
                list.push(row.clone());
                table_pks.insert(pk_key.clone(), idx);
            }

            if table == "apiKeys" {
                if let Some(key_val) = row.get("key").and_then(|v| v.as_str()) {
                    let idx = *table_pks.get(&pk_key).unwrap_or(&0);
                    if let Ok(mut ak_idx) = self.api_key_index.write() {
                        ak_idx.insert(key_val.to_string(), idx);
                    }
                }
            }
        }

        // Mark table dirty
        if let Ok(mut dirty) = self.dirty_tables.write() {
            dirty.insert(table.to_string());
        }

        // Enqueue write
        let should_flush = {
            let mut queue = self.queue.lock().map_err(|e| e.to_string())?;
            queue.insert(
                queue_key,
                PgWriteItem {
                    op: PgWriteOp::Upsert {
                        table: table.to_string(),
                        row,
                    },
                    queued_at: Instant::now(),
                },
            );
            Self::is_critical_table(table) || queue.len() >= MAX_QUEUE_BEFORE_FLUSH
        };

        Ok(should_flush)
    }

    /// Delete a row from memory and queue for write-behind deletion.
    pub fn delete_row(&self, table: &str, keys: HashMap<String, Value>) -> Result<bool, String> {
        let pk_key = primary_key_for_row(table, &keys);
        let queue_key = format!("{}|{}", table, pk_key);

        // Remove from in-memory state
        {
            let mut tables = self.tables.write().map_err(|e| e.to_string())?;
            if let Some(list) = tables.get_mut(table) {
                list.retain(|r| primary_key_for_row(table, r) != pk_key);
            }
            if let Ok(mut pk_guard) = self.pk_index.write() {
                if let Some(table_pks) = pk_guard.get_mut(table) {
                    table_pks.remove(&pk_key);
                }
            }
        }

        // Mark table dirty
        if let Ok(mut dirty) = self.dirty_tables.write() {
            dirty.insert(table.to_string());
        }

        // Enqueue delete
        let should_flush = {
            let mut queue = self.queue.lock().map_err(|e| e.to_string())?;
            queue.insert(
                queue_key,
                PgWriteItem {
                    op: PgWriteOp::Delete {
                        table: table.to_string(),
                        keys,
                    },
                    queued_at: Instant::now(),
                },
            );
            Self::is_critical_table(table) || queue.len() >= MAX_QUEUE_BEFORE_FLUSH
        };

        Ok(should_flush)
    }

    /// O(1) Primary key lookup using in-memory hash index.
    pub fn get_row_by_pk(&self, table: &str, pk: &str) -> Option<HashMap<String, Value>> {
        let pk_guard = self.pk_index.read().ok()?;
        let table_pks = pk_guard.get(table)?;
        let idx = table_pks.get(pk)
            .or_else(|| {
                let cols = conflict_columns(table);
                if cols.len() == 1 {
                    let formatted = format!("{}:{}", cols[0], pk);
                    table_pks.get(&formatted)
                } else {
                    None
                }
            })?;
        let tables = self.tables.read().ok()?;
        tables.get(table)?.get(*idx).cloned()
    }

    /// O(1) Fast API key auth lookup using in-memory key index.
    pub fn get_api_key_by_key(&self, key: &str) -> Option<HashMap<String, Value>> {
        let key_guard = self.api_key_index.read().ok()?;
        let idx = *key_guard.get(key)?;
        let tables = self.tables.read().ok()?;
        tables.get("apiKeys")?.get(idx).cloned()
    }

    /// Get a single row by matching column key-value pairs from in-memory tier.
    pub fn get_row(&self, table: &str, key_values: &[(&str, &Value)]) -> Option<HashMap<String, Value>> {
        let tables = self.tables.read().ok()?;
        let list = tables.get(table)?;
        list.iter().find(|row| {
            key_values.iter().all(|(k, v)| row.get(*k) == Some(*v))
        }).cloned()
    }

    /// Get all rows for a table from in-memory tier.
    pub fn all_rows(&self, table: &str) -> Vec<HashMap<String, Value>> {
        self.tables
            .read()
            .ok()
            .and_then(|t| t.get(table).cloned())
            .unwrap_or_default()
    }

    /// Current queue length.
    pub fn queue_len(&self) -> usize {
        self.queue.lock().map(|q| q.len()).unwrap_or(0)
    }

    /// Drain queue for flushing.
    pub fn drain_queue(&self) -> Vec<PgWriteItem> {
        let mut queue = match self.queue.lock() {
            Ok(q) => q,
            Err(_) => return Vec::new(),
        };
        let items: Vec<PgWriteItem> = queue.drain().map(|(_, item)| item).collect();
        items
    }

    /// Re-enqueue batch items if a transient network failure occurred.
    pub fn requeue_transient_failure(&self, items: Vec<PgWriteItem>) {
        if let Ok(mut queue) = self.queue.lock() {
            for item in items {
                let table = item.op.table();
                let pk = match &item.op {
                    PgWriteOp::Upsert { row, .. } => primary_key_for_row(table, row),
                    PgWriteOp::Delete { keys, .. } => primary_key_for_row(table, keys),
                };
                queue.entry(format!("{}|{}", table, pk)).or_insert(item);
            }
        }
    }

    /// Generate statements and parameter vectors for a drained batch.
    pub fn generate_batch_sql(&self, items: &[PgWriteItem]) -> Vec<(String, Vec<Value>)> {
        let mut results = Vec::new();
        for item in items {
            match &item.op {
                PgWriteOp::Upsert { table, row } => {
                    let mut cols: Vec<&str> = row.keys().map(|s| s.as_str()).collect();
                    cols.sort(); // Stable column order
                    let sql = build_upsert_sql(table, &cols);
                    let params: Vec<Value> = cols.iter().map(|c| row.get(*c).cloned().unwrap_or(Value::Null)).collect();
                    results.push((sql, params));
                }
                PgWriteOp::Delete { table, keys } => {
                    let conflict_cols = conflict_columns(table);
                    let sql = build_delete_sql(table);
                    let params: Vec<Value> = conflict_cols
                        .iter()
                        .map(|c| keys.get(c).cloned().unwrap_or(Value::Null))
                        .collect();
                    results.push((sql, params));
                }
            }
        }
        results
    }

    /// Resync memory table with rows loaded from Postgres, preserving local uncommitted mutations.
    pub fn resync_table(&self, table: &str, remote_rows: Vec<HashMap<String, Value>>) {
        let mut tables = match self.tables.write() {
            Ok(t) => t,
            Err(_) => return,
        };
        let current_list = tables.entry(table.to_string()).or_default();
        let queue = self.queue.lock().ok();

        // Keep local rows that have pending uncommitted writes
        let mut merged: Vec<HashMap<String, Value>> = current_list
            .iter()
            .filter(|local| {
                if let Some(ref q) = queue {
                    let pk = primary_key_for_row(table, local);
                    q.contains_key(&format!("{}|{}", table, pk))
                } else {
                    false
                }
            })
            .cloned()
            .collect();

        let pending_keys: HashSet<String> = merged.iter().map(|r| primary_key_for_row(table, r)).collect();

        for remote in remote_rows {
            let pk = primary_key_for_row(table, &remote);
            if !pending_keys.contains(&pk) {
                merged.push(remote);
            }
        }

        *current_list = merged;
        if let Ok(mut dirty) = self.dirty_tables.write() {
            dirty.remove(table);
        }
    }
}

// ============================================================================
// Unit Tests
